/** La capa 0 completa, tal cual está en `tokens.css`. */
export declare const TOKENS_CSS = "/* ============================================================================\n * @suynda/ui \u2014 capa 0: los tokens.\n *\n * FUENTE DE VERDAD. `src/tokens.ts` se GENERA de este archivo\n * (`scripts/generar-tokens-ts.mjs`) y un test prueba que son byte a byte lo\n * mismo. Editar el .ts a mano rompe esa prueba, a prop\u00F3sito.\n *\n * Todo valor de ac\u00E1 est\u00E1 declarado en `docs/congelado-ui.md` \u00A7A. Ning\u00FAn token\n * existe sin estar en el canon, y el canon no repite valores que est\u00E9n ac\u00E1:\n * el canon dice qu\u00E9 significan, este archivo dice cu\u00E1nto valen.\n * ==========================================================================*/\n\n:root {\n  /* ---- A.1 \u00B7 Color ------------------------------------------------------ */\n\n  /* LA identidad. Puerta plena, franja, acentos.\n     JAM\u00C1S color de texto. JAM\u00C1S bot\u00F3n de acci\u00F3n sobre fondo claro. */\n  --amarillo: #ffc20e;\n\n  /* Texto, siluetas, estructura, acci\u00F3n primaria.\n     El bot\u00F3n primario es tinta con texto blanco. */\n  --tinta: #1f1d1a;\n  --tinta-suave: #3d4a45;\n\n  /* Texto terciario y metadatos. Nunca para dato que importa. */\n  --muted: #6b7772;\n\n  --papel: #f6f7f5;\n  --card: #ffffff;\n  --linea: #e3e7e2;\n\n  --riel: #1c2a25;\n  --riel-hover: #2a3b34;\n\n  /* Sem\u00E1nticos. El fondo suave lleva SU texto, no `--tinta`. */\n  --verde: #0e7a5f;\n  --verde-bg: #e7f3ef;\n  --rojo: #b0453a;\n  --rojo-bg: #f9ecea;\n  --ambar-bg: #fbf1dc;\n  --ambar-tx: #8a6410;\n\n  /* Los dos que s\u00F3lo viven SOBRE el amarillo (\u00A7A.1, promovidos).\n     `--oro` es el \u00FAnico texto leg\u00EDtimo sobre el campo amarillo: su contraste\n     est\u00E1 verificado AA. `--ambar` es profundidad y hover, no texto. */\n  --oro: #7a5b00;\n  --ambar: #e0a200;\n\n  /* ---- A.2 \u00B7 Escala, espaciado y forma ---------------------------------- */\n\n  --tx-xs: 14.5px;\n  --tx-chrome: 15.5px;\n  --tx-sm: 16px;\n  --tx-base: 17px;\n  --tx-lg: 19px;\n\n  --space-1: 0.5rem;\n  --space-2: 1rem;\n  --space-3: 1.5rem;\n  --space-4: 2.5rem;\n  --space-5: 4rem;\n  /* Los dos de abajo son de p\u00E1gina de marketing.\n     El PRODUCTO vive entre --space-1 y --space-5. */\n  --space-6: clamp(4rem, 10vw, 8rem);\n  --space-7: clamp(6rem, 16vw, 12rem);\n\n  --maxw: 1120px;\n  --radio: 12px;\n\n  --sombra: 0 1px 3px rgba(20, 32, 28, 0.07), 0 4px 14px rgba(20, 32, 28, 0.05);\n  --sombra-panel: 0 8px 30px rgba(20, 32, 28, 0.18);\n\n  --foco: 3px solid var(--tinta);\n\n  /* ---- A.3 \u00B7 Tipograf\u00EDa ------------------------------------------------- */\n\n  /* Las caras se auto-hospedan: ver `fuentes/fuentes.css`. `system-ui` queda\n     de respaldo real, no decorativo \u2014 una superficie que todav\u00EDa no sirva los\n     .woff2 cae ah\u00ED y sigue siendo legible. */\n  --tipografia-titulo: Poppins, system-ui, sans-serif;\n  --tipografia-cuerpo: Inter, system-ui, sans-serif;\n}\n";
